const icon=(name,size=20)=>`<svg class="ico" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${I[name]||I.info}</svg>`;
const key='anticor_ai_kz_1';
function loadStore(){try{return JSON.parse(localStorage.getItem(key))||{}}catch{return {}}}
const saved=loadStore();
const state={page:location.hash.replace('#','')||'home',lang:saved.lang||'ru',dark:!!saved.dark,menu:false,status:{},content:{scenarios:[],quiz:[],knowledge:[]},extraScenarios:Array.isArray(saved.extraScenarios)?saved.extraScenarios:[],extraQuiz:Array.isArray(saved.extraQuiz)?saved.extraQuiz:[],profile:saved.profile||{name:'',role:'student'},progress:saved.progress||{},attempts:saved.attempts||[],drafts:saved.drafts||[],consent:false,busy:false,analysisText:'',analysis:null,analysisCategory:'education',chatHistory:[],chatText:'',chatSources:[],draftForm:{facts:'',date:'',place:'',evidence:'',request:''},draftText:'',scenarioActive:null,scenarioAnswer:null,scenarioResult:null,scenarioAi:'',scenarioFilter:'all',scenarioSearch:'',quizRun:null,knowledgeFilter:'all',knowledgeSearch:'',addMode:'scenario',mapCity:'astana'};
const L=()=>i18n[state.lang],t=k=>L()[k]||i18n.ru[k]||k;
function persist(){try{localStorage.setItem(key,JSON.stringify({lang:state.lang,dark:state.dark,extraScenarios:state.extraScenarios,extraQuiz:state.extraQuiz,profile:state.profile,progress:state.progress,attempts:state.attempts,drafts:state.drafts}))}catch{toast('Нет места в хранилище браузера')}}
function scenarios(){return [...state.content.scenarios,...state.extraScenarios]}
function quizzes(){return [...state.content.quiz,...state.extraQuiz]}
function localText(obj,field){return obj?.[field+(state.lang==='kz'?'Kz':'Ru')] ?? obj?.[field+'Ru'] ?? ''}
function sourcesHTML(items){return (items||[]).length?`<div class="result"><h3>${t('sources')}</h3>${items.map(d=>`<div class="ref-card"><a href="${esc(d.url)}" target="_blank" rel="noopener noreferrer">${esc(localText(d,'title'))} ${icon('external',14)}</a><p>${esc(localText(d,'summary'))}</p></div>`).join('')}</div>`:''}
function aiBadge(){return state.status.aiConfigured?`<span class="badge green"><span class="status-dot"></span>${t('sideAi')} · ${esc(state.status.aiProvider||'')}</span>`:`<span class="badge amber"><span class="status-dot off"></span>${t('sideNoAi')}</span>`}
function nav(page){if(page==='features'){state.page='home';state.menu=false;location.hash='home';render();requestAnimationFrame(()=>$('#features-section')?.scrollIntoView({behavior:'smooth',block:'start'}));return}state.page=page;state.menu=false;location.hash=page;state.scenarioActive=page==='training'?state.scenarioActive:null;render();window.scrollTo({top:0,behavior:'instant'})}
const navLinks=['home','features','report','analytics','about'];
function header(){return `<header class="site-header"><div class="header-inner"><button class="hamburger" data-action="menu" aria-label="Меню">${icon('menu')}</button><a href="#home" class="brand" data-page="home"><img src="assets/logo.svg" alt="AntiCor AI KZ logo"><span>AntiCor AI KZ</span></a><nav class="header-links ${state.menu?'show':''}" aria-label="Основная навигация">${navLinks.map(p=>`<button class="nav-link ${state.page===p?'active':''}" data-page="${p}">${t(p)}</button>`).join('')}</nav><div class="header-right"><div class="locale-switch"><button data-action="lang" data-value="kz" class="${state.lang==='kz'?'active':''}" aria-label="Қазақша">Қаз</button><button data-action="lang" data-value="ru" class="${state.lang==='ru'?'active':''}" aria-label="Русский">Рус</button></div><button class="btn btn-light btn-sm" data-page="profile">${icon('user',18)} ${t('profile')}</button></div></div></header>`}
function footer(){return `<footer class="site-footer"><div class="container footer-inner"><div><strong>AntiCor AI KZ</strong><small>${t('footerCopy')}<br>${t('disclaimer')}</small></div><div><a href="https://eotinish.kz/ru" target="_blank" rel="noopener noreferrer">eOtinish ${icon('external',14)}</a> &nbsp; · &nbsp; <button class="inline-link" style="color:#d9e9fa" data-page="about">${t('about')}</button></div></div></footer>`}
function heroPage(title,intro,ico){return `<section class="page-hero"><div class="container page-hero-inner"><div><span class="eyebrow">AntiCor AI KZ</span><h1>${esc(title)}</h1><p>${esc(intro)}</p></div><div class="page-icon">${icon(ico,42)}</div></div></section>`}
function featureCard(ico,title,description,page){return `<button class="feature-card" data-page="${page}"><span class="feature-icon">${icon(ico,29)}</span><span><h3>${title}</h3><p>${description}</p></span></button>`}
function home(){return `<section class="hero"><div class="hero-inner"><div class="hero-content"><span class="eyebrow">${t('homeEyebrow')}</span><h1>AntiCor AI KZ —<br>${t('heroTitle')}</h1><p>${t('heroText')}</p><div class="hero-actions"><button class="btn btn-primary btn-wide" data-page="report">${icon('send')} ${t('heroReport')}</button><button class="btn btn-outline btn-wide" data-page="chat">${icon('spark')} ${t('heroAi')}</button></div><div class="hero-marker"><span></span>${t('heroTrust')}</div></div><div class="hero-art"><img src="assets/hero.svg" alt="Цифровая карта Казахстана и символ искусственного интеллекта"></div></div></section><section id="features-section" class="section landing-block hero-with-grid"><div class="container"><div class="section-heading"><h2>${t('featuresTitle')}</h2><p>${t('featuresSub')}</p></div><div class="feature-grid">${featureCard('shield',t('feat1'),t('feat1d'),'analyze')}${featureCard('chart',t('feat2'),t('feat2d'),'analytics')}${featureCard('chat',t('feat3'),t('feat3d'),'chat')}${featureCard('layers',t('feat4'),t('feat4d'),'knowledge')}</div></div></section><section class="section" style="background:#fff0"><div class="container"><div class="section-heading"><h2>${t('works')}</h2><p>${t('worksSub')}</p></div><div class="steps-grid">${[['file','step1','step1d'],['brain','step2','step2d'],['edit','step3','step3d'],['check','step4','step4d']].map(([ico,title,desc],i)=>`<div class="step"><span class="step-icon">${icon(ico,28)}</span><div><h3>${i+1}. ${t(title)}</h3><p>${t(desc)}</p></div></div>`).join('')}</div></div></section><section class="section" style="padding-top:10px"><div class="container"><div class="home-banner"><div><h2>${t('bannerTitle')}</h2><p>${t('bannerSub')}</p></div><button class="btn btn-primary" data-page="training">${icon('clipboard')} ${t('tryTraining')}</button></div><div class="feature-grid" style="margin-top:22px;grid-template-columns:repeat(2,minmax(0,1fr))">${featureCard('clipboard',t('feat5'),t('feat5d'),'training')}${featureCard('file',t('feat6'),t('feat6d'),'report')}</div></div></section>`}
function consent(){return `<label class="check-row"><input type="checkbox" data-field="consent" ${state.consent?'checked':''}><span>${t('consent')}</span></label>`}
function analyze(){const a=state.analysis?.result;return `${heroPage(t('analyzeTitle'),t('analyzeIntro'),'brain')}<main class="container page-content"><div class="content-grid"><div class="card"><h2>${t('incidentLabel')}</h2><form data-form="analyze"><div class="field"><textarea name="text" maxlength="3000" required minlength="5" placeholder="${esc(t('incidentPlaceholder'))}">${esc(state.analysisText)}</textarea><div class="small muted" style="text-align:right">5–3000</div></div>${consent()}<div class="button-row"><button class="btn btn-primary" type="submit" ${state.busy?'disabled':''}>${state.busy?'<span class="spinner"></span>':icon('spark')} ${state.busy?t('aiBusy'):t('generate')}</button>${a?`<button class="btn btn-ghost" type="button" data-action="export-analysis">${icon('download')} ${t('saveAnswer')}</button>`:''}</div></form>${state.busy?`<div class="notice" style="margin-top:20px">${icon('clock')} ${t('aiBusy')}</div>`:''}${a?`<section class="result" aria-live="polite"><div class="result-top"><h2 style="margin:0">${t('summary')}</h2><span class="badge ${a.risk_level==='elevated'?'red':a.risk_level==='low'?'green':'amber'}">${t('risk')}: ${t(a.risk_level==='elevated'?'riskElevated':a.risk_level==='low'?'riskLow':'riskUnknown')}</span></div><p>${br(a.summary)}</p>${listResult(t('indicators'),a.risk_indicators)}${listResult(t('questions'),a.questions)}${listResult(t('actions'),a.actions)}<div class="notice warning">${esc(a.disclaimer||t('disclaimer'))}</div>${sourcesHTML(state.analysis.sources)}</section>`:''}</div><aside><div class="card"><h3>${t('sideTitle')}</h3><p class="muted">${t('sideDesc')}</p>${aiBadge()}<div class="divider"></div><div class="notice warning">${t('caution')}</div></div><div class="card"><h3>${t('learn')}</h3><p class="muted">${t('feat5d')}</p><button class="btn btn-outline btn-sm" data-page="training">${t('tryTraining')} ${icon('arrow',17)}</button></div></aside></div></main>`}
function listResult(title,items){return `<h3>${esc(title)}</h3>${items?.length?`<ul>${items.map(s=>`<li>${br(s)}</li>`).join('')}</ul>`:`<p class="muted">—</p>`}`}
function chat(){const messages=state.chatHistory.length?state.chatHistory:[{role:'assistant',text:t('chatStart')}];return `${heroPage(t('chatTitle'),t('chatIntro'),'chat')}<main class="container page-content"><div class="content-grid"><div class="card"><div class="row row-between" style="margin-bottom:14px"><div>${aiBadge()}</div><button class="btn btn-ghost btn-sm" data-action="clear-chat">${icon('trash',16)} ${t('clearChat')}</button></div><div class="chat-feed" id="chat-feed" aria-live="polite">${messages.map(msg=>`<div class="bubble ${msg.role==='user'?'user':'ai'}"><div class="chat-label">${msg.role==='user'?(state.lang==='kz'?'Сіз':'Вы'):'AntiCor AI KZ'}</div><p>${esc(msg.text)}</p></div>`).join('')}${state.busy?`<div class="bubble ai"><span class="loading"><span class="spinner"></span>${t('aiBusy')}</span></div>`:''}</div><form data-form="chat"><div class="chat-form"><textarea name="text" maxlength="1600" required minlength="4" placeholder="${esc(t('chatPlaceholder'))}">${esc(state.chatText)}</textarea><button class="btn btn-primary" type="submit" ${state.busy?'disabled':''}>${icon('send')} ${t('send')}</button></div>${consent()}</form>${state.chatSources?.length?sourcesHTML(state.chatSources):''}</div><aside><div class="card"><h3>${t('aboutSafety')}</h3><p class="muted">${t('caution')}</p><div class="notice">${t('disclaimer')}</div></div><div class="card"><h3>${t('sources')}</h3><button class="btn btn-outline btn-sm" data-page="knowledge">${t('knowledge')} ${icon('arrow',17)}</button></div></aside></div></main>`}
function categoryName(value){const labels={education:['Образование','Білім беру'],services:['Госуслуги','Мемлекеттік қызметтер'],employment:['Трудоустройство','Жұмысқа қабылдау'],procurement:['Закупки','Сатып алу'],law:['Законодательство','Заңнама']};return labels[value]?.[state.lang==='ru'?0:1]||value}
function training(){const all=scenarios();const current=all.find(s=>s.id===state.scenarioActive);if(current)return trainingPlay(current);const list=all.filter(s=>(state.scenarioFilter==='all'||s.category===state.scenarioFilter)&&`${localText(s,'title')} ${localText(s,'situation')}`.toLowerCase().includes(state.scenarioSearch.toLowerCase()));return `${heroPage(t('trainingTitle'),t('trainingIntro'),'clipboard')}<main class="container page-content"><div class="row row-between row-wrap" style="margin-bottom:20px"><div><span class="badge green">${Object.values(state.progress).filter(Boolean).length} / ${all.length} ${t('done')}</span></div><div class="button-row"><button class="btn btn-outline btn-sm" data-page="tests">${t('tests')} ${icon('arrow',17)}</button></div></div><div class="toolbar"><input class="search-input" id="scenario-search" placeholder="${esc(t('search'))}" value="${esc(state.scenarioSearch)}"><div class="pill-nav">${['all','education','services','employment','procurement'].map(k=>`<button class="${state.scenarioFilter===k?'active':''}" data-action="filter-scenarios" data-value="${k}">${k==='all'?t('all'):categoryName(k)}</button>`).join('')}</div></div><div class="scenario-list" id="scenario-list">${list.map((s,i)=>`<button class="scenario-card" data-action="start-scenario" data-value="${esc(s.id)}"><div class="row row-between"><span class="badge">${categoryName(s.category)}</span>${state.progress[s.id]?`<span class="badge green">${icon('check',14)} ${t('done')}</span>`:''}</div><h3>${esc(localText(s,'title'))}</h3><p>${esc(localText(s,'situation')).slice(0,150)}...</p><small>${t('go')} →</small></button>`).join('')||`<div class="empty">${t('noData')}</div>`}</div></main>`}
function trainingPlay(s){const answer=state.scenarioAnswer;const result=state.scenarioResult;return `${heroPage(localText(s,'title'),localText(s,'situation'),'clipboard')}<main class="container page-content"><button class="btn btn-ghost btn-sm" data-action="training-back" style="margin-bottom:18px">← ${t('back')}</button><div class="content-grid"><div class="card"><span class="badge">${categoryName(s.category)}</span><h2 style="margin-top:15px">${t('scenarioChoose')}</h2>${(localText(s,'options')||[]).map((option,i)=>`<label class="choice ${answer===i?'chosen':''} ${result!==null && i===s.correct?'correct':''} ${result!==null && answer===i && answer!==s.correct?'incorrect':''}"><input type="radio" name="scenario-choice" value="${i}" ${answer===i?'checked':''} ${result!==null?'disabled':''}><span><b>${String.fromCharCode(65+i)}.</b> ${esc(option)}</span></label>`).join('')}<div class="button-row" style="margin-top:18px">${result===null?`<button class="btn btn-primary" data-action="check-scenario" ${answer===null?'disabled':''}>${t('check')}</button>`:`<button class="btn btn-outline" data-action="training-next">${t('next')} ${icon('arrow',18)}</button>`}</div>${result!==null?`<div class="notice ${result?'success':'warning'}" style="margin-top:20px"><strong>${result?t('correct'):t('incorrect')}</strong><p>${esc(localText(s,'explanation'))}</p></div><div class="button-row" style="margin-top:15px"><button class="btn btn-muted btn-sm" data-action="explain-scenario" ${state.busy?'disabled':''}>${icon('spark',17)} ${state.busy?t('aiBusy'):t('explainAi')}</button></div>${state.scenarioAi?`<div class="ref-card"><strong>AI</strong><p style="white-space:pre-wrap">${esc(state.scenarioAi)}</p></div>`:''}`:''}</div><aside><div class="card"><h3>${t('trainingTitle')}</h3><div class="progress-track"><div style="width:${Math.min(100,Object.values(state.progress).filter(Boolean).length/scenarios().length*100)}%"></div></div><p class="small muted">${Object.values(state.progress).filter(Boolean).length} / ${scenarios().length} ${t('done')}</p><button class="btn btn-outline btn-sm" data-page="tests">${t('tests')}</button></div><div class="card"><div class="notice">${t('disclaimer')}</div></div></aside></div></main>`}
const groups=['basics','cases','rights'];
function quizQuestions(q){const arr=quizzes().filter(x=>x.group===q.group);return q.order?q.order.map(id=>arr.find(x=>x.id===id)).filter(Boolean):arr}
function shuffled(ids){const a=[...ids];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function testGroupTitle(group){return t(group==='basics'?'testBasics':group==='cases'?'testCases':'testRights')}
function tests(){if(state.quizRun)return quizScreen();const arr=groups.map(group=>({group,count:quizzes().filter(q=>q.group===group).length,best:state.attempts.filter(a=>a.group===group).reduce((m,x)=>Math.max(m,x.score),0)}));return `${heroPage(t('testsTitle'),t('testsIntro'),'clipboard')}<main class="container page-content"><div class="cols-3">${arr.map((g,i)=>`<div class="card"><span class="badge">${g.count} ${state.lang==='ru'?'вопросов':'сұрақ'}</span><h2 style="margin-top:17px">${i+1}. ${testGroupTitle(g.group)}</h2><p class="muted">${state.lang==='ru'?'Лучший результат':'Үздік нәтиже'}: <strong>${g.best}%</strong></p><div class="progress-track" style="margin:19px 0"><div style="width:${g.best}%"></div></div><button class="btn btn-primary" data-action="start-quiz" data-value="${g.group}">${t('start')} ${icon('arrow',16)}</button></div>`).join('')}</div></main>`}
function quizScreen(){const q=state.quizRun;const questions=quizQuestions(q);if(q.finished){const score=Math.round(questions.filter((x,i)=>q.answers[x.id]===x.correct).length/questions.length*100);return `${heroPage(t('yourScore'),t('testsIntro'),'award')}<main class="container page-content"><div class="card" style="max-width:850px;margin:auto;text-align:center"><div class="stat-circle">${score}%</div><h2>${testGroupTitle(q.group)}</h2><p class="muted">${questions.length} ${state.lang==='ru'?'вопросов':'сұрақ'}</p><div class="button-row" style="justify-content:center"><button class="btn btn-primary" data-action="start-quiz" data-value="${q.group}">${t('retry')}</button><button class="btn btn-outline" data-action="quit-quiz">${t('back')}</button></div><div class="divider"></div><div style="text-align:left">${questions.map((x,i)=>`<div class="ref-card"><b>${i+1}. ${esc(localText(x,'question'))}</b><p>${t('yourAnswer')}: ${esc(localText(x,'options')?.[q.answers[x.id]]||'—')}</p><p style="color:${q.answers[x.id]===x.correct?'#128a6b':'#bb4653'}">${t('rightAnswer')}: ${esc(localText(x,'options')?.[x.correct])}</p><p>${esc(localText(x,'explanation'))}</p></div>`).join('')}</div></div></main>`}
  const curr=questions[q.index];const answer=q.answers[curr.id];return `${heroPage(testGroupTitle(q.group),t('testsIntro'),'clipboard')}<main class="container page-content"><div class="card" style="max-width:880px;margin:auto"><div class="row row-between"><span class="badge">${q.index+1} / ${questions.length}</span><span class="muted small">${t('testsTitle')}</span></div><div class="progress-track" style="margin:17px 0 27px"><div style="width:${(q.index)/questions.length*100}%"></div></div><h2>${esc(localText(curr,'question'))}</h2>${localText(curr,'options').map((s,i)=>`<label class="choice ${answer===i?'chosen':''}"><input type="radio" name="quiz-choice" value="${i}" ${answer===i?'checked':''}><span>${esc(s)}</span></label>`).join('')}<div class="row row-between" style="margin-top:20px"><button class="btn btn-ghost" data-action="quiz-prev" ${q.index===0?'disabled':''}>← ${t('back')}</button><button class="btn btn-primary" data-action="quiz-next" ${answer===undefined?'disabled':''}>${q.index===questions.length-1?t('finish'):t('next')} ${icon('arrow',16)}</button></div></div></main>`}
function report(){return `${heroPage(t('reportTitle'),t('reportIntro'),'file')}<main class="container page-content"><div class="content-grid"><div class="card"><div class="notice warning" style="margin-bottom:23px">${t('reportNotSubmitted')}. ${t('reportNote')}</div><form data-form="report"><div class="field"><label>${t('reportFacts')} *</label><textarea name="facts" required maxlength="3000" placeholder="${esc(t('incidentPlaceholder'))}">${esc(state.draftForm.facts)}</textarea></div><div class="cols-2"><div class="field"><label>${t('reportDate')}</label><input name="date" type="date" value="${esc(state.draftForm.date)}"></div><div class="field"><label>${t('reportPlace')}</label><input name="place" maxlength="200" value="${esc(state.draftForm.place)}"></div></div><div class="field"><label>${t('reportEvidence')}</label><textarea name="evidence" maxlength="800" style="min-height:88px">${esc(state.draftForm.evidence)}</textarea></div><div class="field"><label>${t('reportRequest')}</label><textarea name="request" maxlength="800" style="min-height:88px">${esc(state.draftForm.request)}</textarea></div>${consent()}<div class="button-row"><button class="btn btn-primary" type="submit" ${state.busy?'disabled':''}>${state.busy?'<span class="spinner"></span>':icon('spark')} ${state.busy?t('aiBusy'):t('reportCreate')}</button></div></form>${state.draftText?`<section class="result"><div class="field"><label>${t('reportTextarea')}</label><textarea id="draft-result" style="min-height:290px">${esc(state.draftText)}</textarea></div><div class="button-row"><button class="btn btn-primary btn-sm" data-action="save-draft">${icon('check',16)} ${t('reportSave')}</button><button class="btn btn-ghost btn-sm" data-action="copy-draft">${icon('file',16)} ${t('reportCopy')}</button><button class="btn btn-ghost btn-sm" data-action="download-draft">${icon('download',16)} ${t('download')} TXT</button><button class="btn btn-outline btn-sm" data-action="print-draft">PDF / Print</button></div></section>`:''}</div><aside><div class="card"><h3>${t('myDrafts')}</h3><div class="draft-list">${state.drafts.length?state.drafts.map(x=>`<div class="draft-row"><div><h4>${esc(x.name)}</h4><p>${esc(x.date)} · ${t('reportNotSubmitted')}</p></div><div class="button-row"><button class="btn btn-ghost btn-sm" title="${t('edit')}" data-action="open-draft" data-value="${esc(x.id)}">${icon('edit',16)}</button><button class="btn btn-danger btn-sm" title="${t('delete')}" data-action="delete-draft" data-value="${esc(x.id)}">${icon('trash',16)}</button></div></div>`).join(''):`<p class="muted">${t('noData')}</p>`}</div></div><div class="card"><h3>${t('reportExternal')}</h3><p class="muted">${t('reportNote')}</p><a class="btn btn-outline btn-sm" href="https://eotinish.kz/ru" target="_blank" rel="noopener noreferrer">${icon('external',16)} eOtinish.kz</a></div></aside></div></main>`}
function analyticsMap(){const cities=[{id:'atyrau',ru:'Атырау',kz:'Атырау',n:12,x:23,y:46},{id:'astana',ru:'Астана',kz:'Астана',n:22,x:52,y:42},{id:'almaty',ru:'Алматы',kz:'Алматы',n:18,x:76,y:76},{id:'shymkent',ru:'Шымкент',kz:'Шымкент',n:9,x:50,y:81},{id:'oskemen',ru:'Өскемен',kz:'Өскемен',n:6,x:80,y:37}];const item=cities.find(c=>c.id===state.mapCity)||cities[1];return `<div class="card" style="margin-top:22px"><h2>${state.lang==='ru'?'Учебная карта ситуаций по регионам':'Аймақтар бойынша оқу жағдаяттарының картасы'}</h2><div class="notice warning">${t('demoDataWarning')} ${state.lang==='ru'?'Метки расположены приблизительно и не показывают реальные события.':'Белгілер шамамен орналасқан, нақты оқиғаларды көрсетпейді.'}</div><div class="geo-grid"><div class="kazmap"><img src="assets/map.svg" alt="Схематичная карта Казахстана">${cities.map(c=>`<button class="city-pin ${c.id===state.mapCity?'selected':''}" style="left:${c.x}%;top:${c.y}%" data-action="map-city" data-value="${c.id}" aria-label="${esc(c.ru)}: ${c.n}">${c.n}</button>`).join('')}</div><div class="geo-details"><span class="badge amber">${state.lang==='ru'?'ДЕМОНСТРАЦИОННЫЕ ДАННЫЕ':'ДЕМОНСТРАЦИЯЛЫҚ ДЕРЕКТЕР'}</span><h3 style="margin-top:15px">${esc(state.lang==='kz'?item.kz:item.ru)}</h3><strong>${item.n}</strong><p>${state.lang==='ru'?'Условных учебных ситуаций в этом примере':'Осы мысалдағы шартты оқу жағдаяттары'}</p><p class="small muted">${state.lang==='ru'?'Выберите другую точку на карте для сравнения.':'Салыстыру үшін картадан басқа нүктені таңдаңыз.'}</p><a href="https://data.egov.kz/" target="_blank" rel="noopener noreferrer">data.egov.kz ${icon('external',15)}</a></div></div></div>`}
function analytics(){const done=Object.values(state.progress).filter(Boolean).length;const n=state.attempts.length;const avg=n?Math.round(state.attempts.reduce((sum,a)=>sum+a.score,0)/n):0;const kpis=[[done,t('metricProgress')],[n,t('metricTests')],[`${avg}%`,t('metricAverage')],[state.drafts.length,t('metricDrafts')]];const sample=[['demoBar1',42],['demoBar2',31],['demoBar3',16],['demoBar4',11]];return `${heroPage(t('analyticsTitle'),t('analyticsIntro'),'chart')}<main class="container page-content"><div class="metric-grid">${kpis.map(([v,l])=>`<div class="kpi"><b>${v}</b><span>${l}</span></div>`).join('')}</div><div class="cols-2" style="margin-top:22px"><div class="card"><h2>${t('demoDataTitle')}</h2><div class="notice warning">${t('demoDataWarning')}</div><div class="chart-rows">${sample.map(([l,v])=>`<div class="chart-row"><span>${t(l)}</span><div class="chart-bar"><div style="width:${v*2}%"></div></div><b>${v}</b></div>`).join('')}</div><p class="note-bottom">${state.lang==='ru'?'Условное распределение 100 учебных ситуаций, не обращений.':'100 оқу жағдайының шартты бөлінісі, нақты өтініштер емес.'}</p></div><div class="card"><h2>${t('testsTitle')}</h2>${groups.map(g=>{const scores=state.attempts.filter(a=>a.group===g);const best=scores.reduce((m,a)=>Math.max(m,a.score),0);return `<div style="margin:17px 0"><div class="row row-between"><span>${testGroupTitle(g)}</span><b>${best}%</b></div><div class="progress-track" style="margin-top:8px"><div style="width:${best}%"></div></div></div>`}).join('')}<div class="divider"></div><button class="btn btn-outline btn-sm" data-action="export-stats">${icon('download',17)} ${t('exportStats')}</button></div></div>${analyticsMap()}<div class="card" style="margin-top:22px"><h2>${t('trainingTitle')}</h2><p class="muted">${done} / ${scenarios().length} ${t('done')}</p><div class="progress-track"><div style="width:${Math.round(done/Math.max(1,scenarios().length)*100)}%"></div></div><div class="button-row" style="margin-top:17px"><button class="btn btn-primary btn-sm" data-page="training">${t('go')} ${icon('arrow',16)}</button></div></div></main>`}
function knowledge(){const list=state.content.knowledge.filter(d=>(state.knowledgeFilter==='all'||d.category===state.knowledgeFilter)&&`${d.titleRu} ${d.titleKz} ${d.summaryRu} ${d.summaryKz}`.toLowerCase().includes(state.knowledgeSearch.toLowerCase()));return `${heroPage(t('knowledgeTitle'),t('knowledgeIntro'),'book')}<main class="container page-content"><div class="toolbar"><input class="search-input" id="knowledge-search" value="${esc(state.knowledgeSearch)}" placeholder="${esc(t('knowledgeSearch'))}"><div class="pill-nav">${['all','law','services','education'].map(k=>`<button class="${state.knowledgeFilter===k?'active':''}" data-action="filter-knowledge" data-value="${k}">${k==='all'?t('all'):categoryName(k)}</button>`).join('')}</div></div><div class="knowledge-grid" id="knowledge-grid">${list.map(d=>`<div class="knowledge-card"><span class="badge">${categoryName(d.category)}</span><h3>${esc(localText(d,'title'))}</h3><p>${esc(localText(d,'summary'))}</p><a href="${esc(d.url)}" target="_blank" rel="noopener noreferrer">${t('openSource')} ${icon('external',16)}</a></div>`).join('')}</div></main>`}
function profile(){return `${heroPage(t('profileTitle'),t('profileIntro'),'user')}<main class="container page-content"><div class="profile-panel"><div class="card"><h2>${t('profileTitle')}</h2><form data-form="profile"><div class="field"><label>${t('nickname')}</label><input name="name" maxlength="70" value="${esc(state.profile.name)}" placeholder="${state.lang==='ru'?'Ваше имя (необязательно)':'Атыңыз (міндетті емес)'}"></div><div class="field"><label>${t('role')}</label><select name="role"><option value="student" ${state.profile.role==='student'?'selected':''}>${t('roleStudent')}</option><option value="teacher" ${state.profile.role==='teacher'?'selected':''}>${t('roleTeacher')}</option></select></div><div class="button-row"><button class="btn btn-primary" type="submit">${t('save')}</button><button type="button" class="btn btn-ghost" data-action="theme">${icon(state.dark?'sun':'moon',17)} ${state.dark?'Light':'Dark'}</button></div></form></div>${state.profile.role==='teacher'?editor():''}<div class="card"><h2>${t('export')} / ${t('import')}</h2><div class="button-row"><button class="btn btn-outline btn-sm" data-action="export-content">${icon('download',16)} ${t('export')}</button><label class="btn btn-ghost btn-sm" style="cursor:pointer">${icon('file',16)} ${t('import')}<input type="file" id="import-content" class="file-control" accept=".json,application/json"></label><button class="btn btn-danger btn-sm" data-action="reset">${icon('trash',16)} ${t('reset')}</button></div><p class="note-bottom">${t('profileIntro')}</p></div></div></main>`}
function editor(){return `<div class="card"><h2>${t('editorTitle')}</h2><p class="muted">${t('editorIntro')}</p><div class="notice warning" style="margin-bottom:16px">${t('teacherHint')}</div><div class="pill-nav" style="margin-bottom:20px"><button data-action="editor-mode" data-value="scenario" class="${state.addMode==='scenario'?'active':''}">${t('editorScenario')}</button><button data-action="editor-mode" data-value="quiz" class="${state.addMode==='quiz'?'active':''}">${t('editorQuiz')}</button></div><form data-form="editor" class="teacher-form"><input type="hidden" name="kind" value="${state.addMode}"><div class="cols-2"><div class="field"><label>${state.addMode==='quiz'?t('quizTitleRu'):t('scTitleRu')}</label><input required name="titleRu" maxlength="240"></div><div class="field"><label>${state.addMode==='quiz'?t('quizTitleKz'):t('scTitleKz')}</label><input required name="titleKz" maxlength="240"></div></div>${state.addMode==='scenario'?`<div class="cols-2"><div class="field"><label>${t('scSituationRu')}</label><textarea required name="situationRu" maxlength="1500"></textarea></div><div class="field"><label>${t('scSituationKz')}</label><textarea required name="situationKz" maxlength="1500"></textarea></div></div>`:''}<div class="cols-2"><div class="field"><label>${t('scOptionsRu')}</label><textarea required name="optionsRu" placeholder="A\nB\nC\nD"></textarea></div><div class="field"><label>${t('scOptionsKz')}</label><textarea required name="optionsKz" placeholder="A\nB\nC\nD"></textarea></div></div><div class="field"><label>${t('scCorrect')}</label><select name="correct">${[1,2,3,4].map(n=>`<option value="${n-1}">${n}</option>`).join('')}</select></div><div class="cols-2"><div class="field"><label>Пояснение (RU)</label><textarea name="explanationRu" required></textarea></div><div class="field"><label>Түсіндірме (KZ)</label><textarea name="explanationKz" required></textarea></div></div><button class="btn btn-primary" type="submit">${icon('check',17)} ${t('create')}</button></form><p class="note-bottom">${state.lang==='ru'?'Добавленные вами:':'Қосылғандар:'} ${state.extraScenarios.length} ${t('training').toLowerCase()}, ${state.extraQuiz.length} ${t('tests').toLowerCase()}.</p></div>`}
function about(){return `${heroPage(t('aboutTitle'),t('aboutIntro'),'shield')}<main class="container page-content"><div class="cols-2"><div class="card"><div class="feature-icon" style="margin-bottom:16px">${icon('brain',28)}</div><h2>AntiCor AI KZ</h2><p>${t('aboutMain')}</p><div class="notice">${t('disclaimer')}</div></div><div class="card"><div class="feature-icon" style="margin-bottom:16px">${icon('lock',28)}</div><h2>${t('aboutSafety')}</h2><p>${t('aboutSafetyText')}</p></div><div class="card"><div class="feature-icon" style="margin-bottom:16px">${icon('file',28)}</div><h2>${t('aboutTechnology')}</h2><p>${t('aboutTechnologyText')}</p><p>${aiBadge()}</p></div><div class="card"><div class="feature-icon" style="margin-bottom:16px">${icon('external',28)}</div><h2>${t('aboutLegal')}</h2><p>${t('aboutLegalText')}</p><a href="https://eotinish.kz/ru" target="_blank" rel="noopener noreferrer">eOtinish.kz ${icon('external',16)}</a></div></div></main>`}
function render(){document.documentElement.lang=state.lang==='kz'?'kk':'ru';document.body.classList.toggle('dark',state.dark);const pages={home,features:()=>home(),analyze,chat,training,tests,report,analytics,knowledge,profile,about};const current=pages[state.page]||home;$('#app').innerHTML=header()+current()+footer();if(state.page==='chat'){const feed=$('#chat-feed');if(feed)feed.scrollTop=feed.scrollHeight;}}
function toast(msg){$('.toast')?.remove();const node=document.createElement('div');node.className='toast';node.textContent=msg;document.body.appendChild(node);setTimeout(()=>node.remove(),4000)}
function download(filename,text,mime='text/plain;charset=utf-8'){const blob=new Blob([text],{type:mime});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function copy(text){try{await navigator.clipboard.writeText(text);toast(t('copySuccess'))}catch{download('anticor-text.txt',text);toast(t('download'))}}
function ensureConsent(){if(state.consent)return true;toast(t('consent'));return false}
async function aiRequest(type,text,extras={}){if(!state.status?.aiConfigured){toast(state.lang==='kz'?'ЖИ функциясы үшін Netlify Functions және API кілті қажет.':'Для настоящего ИИ требуется полная Netlify-версия с Functions и API-ключом.');return null}if(!ensureConsent())return null;state.busy=true;render();try{const res=await fetch('/api/ai/'+type,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text,lang:state.lang,consent:true,...extras})});const data=await res.json();if(!res.ok)throw new Error(data.message||'AI error');return data}catch(e){toast(e.message||t('aiUnavailable'));return null}finally{state.busy=false;render()}}
function buildDraftText(data){return [data.facts,data.date?`Дата / Күні: ${data.date}`:'',data.place?`Место / Орын: ${data.place}`:'',data.evidence?`Подтверждения / Дәлелдер: ${data.evidence}`:'',data.request?`Прошу / Сұраймын: ${data.request}`:''].filter(Boolean).join('\n')}
function gather(form){return Object.fromEntries(new FormData(form).entries())}
function safeOptions(text){return String(text||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean)}
function addEditorData(data){const optionsRu=safeOptions(data.optionsRu),optionsKz=safeOptions(data.optionsKz);if(optionsRu.length!==4||optionsKz.length!==4)throw new Error('Требуется ровно 4 варианта в каждом языке / Әр тілде 4 жауап қажет');const base={id:'custom-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),optionsRu,optionsKz,correct:Number(data.correct),explanationRu:data.explanationRu.trim(),explanationKz:data.explanationKz.trim()};if(data.kind==='scenario'){state.extraScenarios.push({...base,category:'education',titleRu:data.titleRu.trim(),titleKz:data.titleKz.trim(),situationRu:data.situationRu.trim(),situationKz:data.situationKz.trim()});}else{state.extraQuiz.push({...base,group:'cases',questionRu:data.titleRu.trim(),questionKz:data.titleKz.trim()});}persist();toast(t('saved'));render()}
function validateImport(raw){if(!raw||typeof raw!=='object'||!Array.isArray(raw.extraScenarios)||!Array.isArray(raw.extraQuiz))throw new Error('Incorrect JSON structure');if(raw.extraScenarios.length>150||raw.extraQuiz.length>400)throw new Error('Too many records');for(const s of raw.extraScenarios){if(!s||typeof s.titleRu!=='string'||typeof s.titleKz!=='string'||!Array.isArray(s.optionsRu)||s.optionsRu.length!==4||s.optionsKz?.length!==4||!Number.isInteger(s.correct)||s.correct<0||s.correct>3)throw new Error('Invalid scenario');}for(const q of raw.extraQuiz){if(!q||typeof q.questionRu!=='string'||typeof q.questionKz!=='string'||!Array.isArray(q.optionsRu)||q.optionsRu.length!==4||q.optionsKz?.length!==4||!Number.isInteger(q.correct)||q.correct<0||q.correct>3)throw new Error('Invalid question');}return {extraScenarios:raw.extraScenarios.map((s,i)=>({...s,id:'import-s-'+Date.now()+'-'+i,category:['education','services','employment','procurement'].includes(s.category)?s.category:'education'})),extraQuiz:raw.extraQuiz.map((q,i)=>({...q,id:'import-q-'+Date.now()+'-'+i,group:groups.includes(q.group)?q.group:'cases'}))};}

document.addEventListener('click',async e=>{
 const go=e.target.closest('[data-page]');if(go){e.preventDefault();nav(go.dataset.page);return}
 const a=e.target.closest('[data-action]');if(!a)return;
 const action=a.dataset.action,value=a.dataset.value;
 if(action==='menu'){state.menu=!state.menu;render()}
 if(action==='lang'){state.lang=value;persist();render()}
 if(action==='theme'){state.dark=!state.dark;persist();render()}
 if(action==='filter-scenarios'){state.scenarioFilter=value;render()}
 if(action==='filter-knowledge'){state.knowledgeFilter=value;render()}
 if(action==='map-city'){state.mapCity=value;render()}
 if(action==='start-scenario'){state.scenarioActive=value;state.scenarioAnswer=null;state.scenarioResult=null;state.scenarioAi='';render();window.scrollTo(0,0)}
 if(action==='training-back'){state.scenarioActive=null;state.scenarioAnswer=null;state.scenarioResult=null;state.scenarioAi='';render()}
 if(action==='check-scenario'){const s=scenarios().find(x=>x.id===state.scenarioActive);if(s&&state.scenarioAnswer!==null){state.scenarioResult=state.scenarioAnswer===s.correct;state.progress[s.id]=true;persist();render()}}
 if(action==='training-next'){const arr=scenarios();const idx=arr.findIndex(s=>s.id===state.scenarioActive);const next=arr[(idx+1)%arr.length];state.scenarioActive=next.id;state.scenarioAnswer=null;state.scenarioResult=null;state.scenarioAi='';render();window.scrollTo(0,0)}
 if(action==='explain-scenario'){const s=scenarios().find(x=>x.id===state.scenarioActive);if(!s)return;const text=`${localText(s,'situation')}\n${state.lang==='ru'?'Правильный вариант':'Дұрыс жауап'}: ${localText(s,'options')[s.correct]}\n${state.lang==='ru'?'Объяснение':'Түсіндірме'}: ${localText(s,'explanation')}`;const data=await aiRequest('explain',text);if(data){state.scenarioAi=data.answer;render()}}
 if(action==='start-quiz'){state.quizRun={group:value,index:0,answers:{},finished:false,order:shuffled(quizzes().filter(x=>x.group===value).map(x=>x.id))};render();window.scrollTo(0,0)}
 if(action==='quiz-prev'){state.quizRun.index=Math.max(0,state.quizRun.index-1);render()}
 if(action==='quiz-next'){const q=state.quizRun;const questions=quizQuestions(q);if(q.answers[questions[q.index].id]===undefined)return;if(q.index===questions.length-1){q.finished=true;const score=Math.round(questions.filter(x=>q.answers[x.id]===x.correct).length/questions.length*100);state.attempts.push({group:q.group,score,date:new Date().toISOString()});persist()}else q.index++;render();window.scrollTo(0,0)}
 if(action==='quit-quiz'){state.quizRun=null;render()}
 if(action==='clear-chat'){state.chatHistory=[];state.chatSources=[];state.chatText='';render()}
 if(action==='export-analysis'&&state.analysis){const r=state.analysis.result;download('anticor-analysis.txt',`${t('summary')}: ${r.summary}\n${t('risk')}: ${r.risk_level}\n${t('indicators')}: ${r.risk_indicators.join('; ')}\n${t('questions')}: ${r.questions.join('; ')}\n${t('actions')}: ${r.actions.join('; ')}\n${r.disclaimer}\n${state.analysis.sources.map(s=>s.url).join('\n')}`)}
 if(action==='save-draft'){const d=$('#draft-result');if(d)state.draftText=d.value;if(!state.draftText.trim())return;state.drafts.unshift({id:'d'+Date.now(),name:state.draftText.trim().slice(0,52),date:new Date().toLocaleDateString('ru-RU'),text:state.draftText});state.drafts=state.drafts.slice(0,25);persist();toast(t('saved'));render()}
 if(action==='copy-draft'){state.draftText=$('#draft-result')?.value??state.draftText;await copy(state.draftText)}
 if(action==='download-draft'){state.draftText=$('#draft-result')?.value??state.draftText;download('anticor-appeal-draft.txt',state.draftText)}
 if(action==='print-draft'){state.draftText=$('#draft-result')?.value??state.draftText;const win=window.open('','_blank');if(!win){toast('Разрешите всплывающие окна для печати');return}const doc=win.document;doc.title='AntiCor AI KZ — черновик обращения';const p=doc.createElement('pre');p.textContent=state.draftText;p.style.cssText='white-space:pre-wrap;font-family:Arial,sans-serif;font-size:14px;line-height:1.6;margin:40px';const note=doc.createElement('p');note.textContent=t('reportNotSubmitted');note.style.cssText='font-family:Arial;color:#666;font-size:12px;margin:30px 40px';doc.body.append(p,note);win.focus();win.print()}
 if(action==='open-draft'){const d=state.drafts.find(x=>x.id===value);if(d){state.draftText=d.text;render();window.scrollTo(0,200)}}
 if(action==='delete-draft'&&confirm(t('deleteConfirm'))){state.drafts=state.drafts.filter(x=>x.id!==value);persist();render()}
 if(action==='export-stats'){const csv='group,score,date\n'+state.attempts.map(a=>`${a.group},${a.score},${a.date}`).join('\n');download('anticor-learning-results.csv','\uFEFF'+csv,'text/csv;charset=utf-8')}
 if(action==='editor-mode'){state.addMode=value;render()}
 if(action==='export-content'){download('anticor-added-content.json',JSON.stringify({extraScenarios:state.extraScenarios,extraQuiz:state.extraQuiz},null,2),'application/json')}
 if(action==='reset'&&confirm(t('resetConfirm'))){localStorage.removeItem(key);state.profile={name:'',role:'student'};state.progress={};state.attempts=[];state.drafts=[];state.extraScenarios=[];state.extraQuiz=[];render()}
});
document.addEventListener('change',async e=>{
 if(e.target.matches('[data-field="consent"]')){state.consent=e.target.checked;return}
 if(e.target.name==='scenario-choice'){state.scenarioAnswer=Number(e.target.value);render();return}
 if(e.target.name==='quiz-choice'){const q=state.quizRun;const question=quizQuestions(q)[q.index];q.answers[question.id]=Number(e.target.value);render();return}
 if(e.target.id==='import-content'&&e.target.files?.[0]){try{const file=e.target.files[0];if(file.size>400_000)throw new Error('Файл больше 400 КБ');const parsed=validateImport(JSON.parse(await file.text()));state.extraScenarios=parsed.extraScenarios;state.extraQuiz=parsed.extraQuiz;persist();toast(t('saved'));render()}catch(err){toast(err.message)}}
});
document.addEventListener('input',e=>{
 if(e.target.id==='scenario-search'){state.scenarioSearch=e.target.value;$$('.scenario-card').forEach(card=>{card.style.display=card.textContent.toLowerCase().includes(state.scenarioSearch.toLowerCase())?'':'none'})}
 if(e.target.id==='knowledge-search'){state.knowledgeSearch=e.target.value;$$('.knowledge-card').forEach(card=>{card.style.display=card.textContent.toLowerCase().includes(state.knowledgeSearch.toLowerCase())?'':'none'})}
 if(e.target.id==='draft-result'){state.draftText=e.target.value}
});
document.addEventListener('submit',async e=>{
 const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();if(state.busy)return;
 const data=gather(form),kind=form.dataset.form;
 if(kind==='analyze'){state.analysisText=data.text||'';if(!state.analysisText.trim())return;const result=await aiRequest('analyze',state.analysisText);if(result){state.analysis=result;render()}}
 if(kind==='chat'){const text=(data.text||'').trim();if(!text)return;const prior=state.chatHistory.slice(-6);state.chatHistory.push({role:'user',text});state.chatText='';const result=await aiRequest('chat',text,{history:prior});if(result){state.chatHistory.push({role:'assistant',text:result.answer});state.chatSources=result.sources;render()}}
 if(kind==='report'){state.draftForm={facts:data.facts||'',date:data.date||'',place:data.place||'',evidence:data.evidence||'',request:data.request||''};if(!state.draftForm.facts.trim())return;const result=await aiRequest('draft',buildDraftText(state.draftForm));if(result){state.draftText=result.draft;render()}}
 if(kind==='profile'){state.profile={name:(data.name||'').slice(0,70),role:data.role==='teacher'?'teacher':'student'};persist();toast(t('profileSaved'));render()}
 if(kind==='editor'){try{addEditorData(data)}catch(err){toast(err.message)}}
});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1)||'home';if(p!==state.page){state.page=p;render()}});
async function init(){try{const [s,c]=await Promise.all([fetch('data/status.json').then(r=>r.json()),fetch('data/content.json').then(r=>r.json())]);state.status=s;state.content=c}catch(err){toast('Ошибка подключения к серверу: '+err.message)}render()}
init();
